# Candidate 2: merge source colors that share a legend output color, and preserve all paired motif cells.
active_motifs = {
  2: [(6,15),(6,16),(7,16),(9,13),(10,13),(10,14)],
  3: [(5,8),(5,9),(6,8),(7,10),(8,9),(8,10)],
  6: [(4,6),(4,7),(5,6),(6,13),(7,12),(7,13)],
  7: [(1,6),(1,7),(2,6),(10,8),(11,7),(11,8)],
}
active_cells={p for pts in active_motifs.values() for p in pts}
group_boxes=[
  (4, (5,10,8,16)), # merged sources 3 and 2
  (1, (1,11,6,8)),
  (8, (4,7,6,13)),
]
out3=[row[:] for row in grid]
for fill,(r0,r1,c0,c1) in group_boxes:
  for r in range(r0,r1+1):
    for c in range(c0,c1+1):
      if (r,c) not in active_cells:
        out3[r][c]=fill
