# Sequential fills: 7->1, 6->8, then all source hues mapping to 4 share one region.
for fill,box,keep in [(1,(1,11,6,8),{7}),(8,(4,7,6,13),{6}),(4,(5,10,8,16),{2,3})]:
  r0,r1,c0,c1=box
